// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SiteContentRevision) predicate.SiteContentRevision {
	return predicate.SiteContentRevision(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SiteContentRevision) predicate.SiteContentRevision {
	return predicate.SiteContentRevision(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SiteContentRevision) predicate.SiteContentRevision {
	return predicate.SiteContentRevision(sql.NotPredicates(p))
}
